import * as repo from "@/server/repositories/mess/test";
import { applyTestRules } from "@/server/policy/mess/test";
import { auditWrite } from "@/server/services/audit/write";

export interface TestInput {
  actorId: string;
  actorRole: string;
  // TODO: add your input fields
}

export interface TestResult {
  id: string;
  // TODO: add your output fields
}

export async function listTest(input: TestInput): Promise<TestResult[]> {
  const decision = applyTestRules({ action: "list", role: input.actorRole });
  if (!decision.allowed) throw new Error(`FORBIDDEN:${decision.reason ?? "policy"}`);
  return repo.findAll();
}

export async function createTest(input: TestInput): Promise<TestResult> {
  const decision = applyTestRules({ action: "create", role: input.actorRole });
  if (!decision.allowed) throw new Error(`FORBIDDEN:${decision.reason ?? "policy"}`);

  const row = await repo.insert({ createdBy: input.actorId });

  // Audit failures never block the write.
  try {
    await auditWrite({
      action: "TEST_CREATED",
      userId: input.actorId,
      details: { id: row.id },
    });
  } catch { /* non-fatal */ }

  return row;
}

export async function deleteTest(id: string, input: TestInput): Promise<boolean> {
  const decision = applyTestRules({ action: "delete", role: input.actorRole });
  if (!decision.allowed) throw new Error(`FORBIDDEN:${decision.reason ?? "policy"}`);

  const deleted = await repo.remove(id);

  try {
    await auditWrite({
      action: "TEST_DELETED",
      userId: input.actorId,
      details: { id },
    });
  } catch { /* non-fatal */ }

  return deleted;
}
